import hashlib
from datetime import datetime
from datetime import timedelta

import pytest
from freezegun import freeze_time

from itsdangerous.exc import BadSignature
from itsdangerous.exc import SignatureExpired
from itsdangerous.timed import TimedSerializer


class TestTimedSerializerFallback(object):
    @pytest.fixture()
    def ts(self):
        return datetime(2011, 6, 24, 0, 9, 5)

    @pytest.fixture(autouse=True)
    def freeze(self, ts):
        with freeze_time(ts) as ft:
            yield ft

    def test_fallback_signers_return_timestamp(self, ts):
        old = TimedSerializer(
            secret_key="foo", signer_kwargs={"digest_method": hashlib.sha512}
        )
        signed = old.dumps([1, 2, 3])

        new = TimedSerializer(
            secret_key="foo",
            signer_kwargs={"digest_method": hashlib.sha1},
            fallback_signers=[{"digest_method": hashlib.sha512}],
        )
        payload, timestamp = new.loads(signed, return_timestamp=True)
        assert payload == [1, 2, 3]
        assert timestamp == ts

    def test_fallback_signers_expired_still_raises(self, ts, freeze):
        old = TimedSerializer(
            secret_key="foo", signer_kwargs={"digest_method": hashlib.sha512}
        )
        signed = old.dumps([1, 2, 3])
        freeze.tick(timedelta(seconds=11))

        new = TimedSerializer(
            secret_key="foo",
            signer_kwargs={"digest_method": hashlib.sha1},
            fallback_signers=[{"digest_method": hashlib.sha512}],
        )

        with pytest.raises(SignatureExpired) as exc_info:
            new.loads(signed, max_age=10)

        assert exc_info.value.date_signed == ts
        assert new.load_payload(exc_info.value.payload) == [1, 2, 3]

    def test_fallback_signers_none_match(self):
        unrelated = TimedSerializer(
            secret_key="bar", signer_kwargs={"digest_method": hashlib.sha512}
        )
        signed = unrelated.dumps([1, 2, 3])

        serializer = TimedSerializer(
            secret_key="foo",
            signer_kwargs={"digest_method": hashlib.sha1},
            fallback_signers=[{"digest_method": hashlib.sha512}],
        )

        with pytest.raises(BadSignature):
            serializer.loads(signed)

    def test_fallback_signers_with_salt(self):
        old = TimedSerializer(
            secret_key="foo", signer_kwargs={"digest_method": hashlib.sha512}
        )
        signed = old.dumps([1, 2, 3], salt="other-salt")

        new = TimedSerializer(
            secret_key="foo",
            signer_kwargs={"digest_method": hashlib.sha1},
            fallback_signers=[{"digest_method": hashlib.sha512}],
        )

        with pytest.raises(BadSignature):
            new.loads(signed)

        assert new.loads(signed, salt="other-salt") == [1, 2, 3]
